import { CONTENT_INPUTS, CONTENT_KINDS, PENDING, RECORD_KINDS, ROLES, TARGET_KINDS, TEXT } from './contracts.js';

export const escapeHtml = value => String(value ?? '').replace(/[&<>'"]/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' })[char]);
const e = escapeHtml;
const money = value => `¥${Number(value || 0).toLocaleString('zh-CN')}`;
const attr = value => e(value).replaceAll('\n', '&#10;');
const ICONS = {
  dashboard: '<rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/>',
  users: '<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>',
  deal: '<path d="M20 7h-4V3H8v4H4a2 2 0 0 0-2 2v10a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V9a2 2 0 0 0-2-2z"/><path d="M8 7h8M12 11v6M9 14h6"/>',
  export: '<path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><path d="M7 10l5 5 5-5M12 15V3"/>',
  settings: '<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06-2.83 2.83-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21h-4v-.09a1.65 1.65 0 0 0-1-1.51 1.65 1.65 0 0 0-1.82.33l-.06.06-2.83-2.83.06-.06A1.65 1.65 0 0 0 4.6 15a1.65 1.65 0 0 0-1.51-1H3v-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06L7.04 4.3l.06.06A1.65 1.65 0 0 0 8.92 4a1.65 1.65 0 0 0 1-1.51V2h4v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06 2.83 2.83-.06.06A1.65 1.65 0 0 0 19.4 9c.12.61.66 1.05 1.28 1.05H21v4h-.32c-.62 0-1.16.44-1.28 1.05z"/>',
  image: '<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><path d="M21 15l-5-5L5 21"/>',
  file: '<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6"/>',
  message: '<path d="M21 15a4 4 0 0 1-4 4H8l-5 3V7a4 4 0 0 1 4-4h10a4 4 0 0 1 4 4z"/>',
  clock: '<circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/>'
};
const icon = name => `<span class="nav-icon"><svg viewBox="0 0 24 24" aria-hidden="true">${ICONS[name] ?? ICONS.file}</svg></span>`;
const opt = (value, label, selected) => `<option value="${e(value)}" ${value === selected ? 'selected' : ''}>${e(label)}</option>`;
const options = (items, selected) => Object.entries(items).map(([value, label]) => opt(value, label, selected)).join('');
const button = (label, attributes = '', primary = false) => `<button class="btn ${primary ? 'btn-primary' : ''}" ${attributes}>${e(label)}</button>`;
const card = (title, body, action = '') => `<section class="card section-card"><div class="card-head"><div class="card-title">${e(title)}</div>${action}</div><div class="card-body">${body}</div></section>`;
const note = message => `<p class="section-note">${e(message)}</p>`;
const pending = message => `<div class="pending-note"><span class="status status-wait">说明</span><span>${e(message)}</span></div>`;
const table = (headers, rows, empty = TEXT.empty) => `<div class="table-scroll"><table class="data-table"><thead><tr>${headers.map(label => `<th>${e(label)}</th>`).join('')}</tr></thead><tbody>${rows.map(row => `<tr>${row.map(value => `<td>${value?.html ?? e(value)}</td>`).join('')}</tr>`).join('')}${rows.length ? '' : `<tr><td class="empty-cell" colspan="${headers.length}">${e(empty)}</td></tr>`}</tbody></table></div>`;
const field = (label, control, wide = false) => `<label class="form-field ${wide ? 'full' : ''}"><span class="field-label">${e(label)}</span>${control}</label>`;
const input = (name, label, value = '', type = 'text', extra = '', placeholder = '') => field(label, `<input name="${name}" type="${type}" value="${attr(value)}" placeholder="${attr(placeholder)}" ${extra}>`);
const textarea = (name, label, value = '', extra = '', placeholder = '') => field(label, `<textarea name="${name}" placeholder="${attr(placeholder)}" ${extra}>${e(value)}</textarea>`, true);
const select = (name, label, items, selected = '', extra = '') => field(label, `<select name="${name}" ${extra}>${options(items, selected)}</select>`);
const customerOptions = data => Object.fromEntries(data.allCustomers.map(row => [row.id, `${row.name} · ${row.account}`]));
const customerSelect = (data, selected = '') => select('customerId', '客户', customerOptions(data), selected, 'required');
const form = (type, fields, enabled = true, label = TEXT.save) => `<form data-form="${type}"><div class="form-grid">${fields}</div><div class="form-actions"><span>${e(TEXT.localOnly)}</span>${button(label, `type="submit" ${enabled ? '' : 'disabled'}`, true)}</div></form>`;
const actionButton = (label, message, primary = false) => button(label, `type="button" data-prototype-action="${attr(message)}"`, primary);
const accountOptions = data => Object.fromEntries([['', '全部企微账号'], ...data.accounts.map(row => [row.id, row.label])]);
const filterBar = data => `<form class="toolbar customer-filter" data-filter><div class="filters">${input('query', '搜索联系人', data.filters.query, 'search', '', '昵称、备注、手机或微信号')}${input('start', '添加开始日期', data.filters.start, 'date')}${input('end', '添加结束日期', data.filters.end, 'date')}${select('account', '企微账号', accountOptions(data), data.filters.account)}${select('tag', '客户标签', { '': '全部标签', ...Object.fromEntries(data.tagOptions.map(tag => [tag, tag])) }, data.filters.tag)}</div><div class="filter-actions">${button('重置', 'type="button" data-reset-filter')}${button('筛选', 'type="submit"', true)}</div></form>`;
const customerById = (data, id) => data.allCustomers.find(row => row.id === id) ?? data.allCustomers[0];
const conversationById = data => data.conversations.find(row => row.id === data.ui?.activeConversationId) ?? data.conversations[0];

export const dashboardView = data => {
  const projectItems = Object.fromEntries([['', '全部项目'], ...data.projectOptions.map(project => [project, project])]);
  const ownerItems = Object.fromEntries([['', '全部销售'], ...data.ownerOptions.map(owner => [owner, owner])]);
  const sourceItems = Object.fromEntries([['', '全部来源'], ...data.sourceOptions.map(source => [source, source])]);
  const maxTrend = Math.max(...data.dashboard.trend.map(row => row.amount), 1);
  const maxSource = Math.max(...data.dashboard.sourceSummary.map(row => row.count), 1);
  return `<form class="toolbar dashboard-filter" data-filter><div class="filters">${input('start', '统计开始日期', data.filters.start, 'date')}${input('end', '统计结束日期', data.filters.end, 'date')}${select('project', '成交项目', projectItems, data.filters.project)}${select('account', '企微账号', accountOptions(data), data.filters.account)}${select('owner', '归属销售', ownerItems, data.filters.owner)}${select('source', '客户来源', sourceItems, data.filters.source)}</div><div class="filter-actions">${button('重置', 'type="button" data-reset-filter')}${button('查询看板', 'type="submit"', true)}</div></form>
  <div class="dashboard-scope-note"><span>统计口径</span>客户按添加时间统计；咨询按登记时间统计；成交与退费按业务发生时间统计。所有结果受当前角色和企微账号数据范围限制。</div>
  <div class="overview-grid dashboard-kpis dashboard-kpis-six">
    ${card('新增客户数', `<strong class="metric-value">${data.dashboard.newCustomers}</strong><p>当前筛选周期新增联系人</p>`, button('客户明细', 'data-route="customers"'))}
    ${card('咨询客户数', `<strong class="metric-value">${data.dashboard.consultations}</strong><p>已登记咨询记录的客户</p>`, button('咨询明细', 'data-route="records"'))}
    ${card('成交单数', `<strong class="metric-value">${data.dashboard.deals}</strong><p>成交转化率 ${data.dashboard.conversion}%</p>`, button('成交明细', 'data-route="transactions"'))}
    ${card('成交金额', `<strong class="metric-value">${money(data.dashboard.total)}</strong><p>原始成交金额合计</p>`)}
    ${card('退费金额', `<strong class="metric-value warning">${money(data.dashboard.refundTotal)}</strong><p>审批中与已通过退费</p>`, button('退费明细', 'data-route="transactions"'))}
    ${card('净成交金额', `<strong class="metric-value success">${money(data.dashboard.net)}</strong><p>成交金额减退费金额</p>`, button('导出业绩', 'data-export="performance"'))}
  </div>
  <div class="dashboard-analytics">
    ${card('客户转化漏斗', `<div class="funnel-chart">${data.dashboard.funnel.map((row, index) => `<div style="width:${100 - index * 14}%"><span>${e(row.label)}</span><strong>${row.value} 人</strong></div>`).join('')}</div><div class="funnel-foot"><span>总体成交转化率</span><strong>${data.dashboard.conversion}%</strong></div>`)}
    ${card('成交趋势', `<div class="trend-chart">${data.dashboard.trend.map(row => `<div class="trend-column"><span class="trend-value">${money(row.amount)}</span><i style="height:${Math.max(18, Math.round(row.amount / maxTrend * 125))}px"></i><b>${row.count} 单</b><small>${e(row.date.slice(5))}</small></div>`).join('') || '<p class="empty-cell">当前筛选范围暂无成交</p>'}</div>`, button('查看成交', 'data-route="transactions"'))}
    ${card('客户来源分布', `<div class="source-bars">${data.dashboard.sourceSummary.map(row => `<div><span>${e(row.value)}</span><i><b style="width:${Math.round(row.count / maxSource * 100)}%"></b></i><strong>${row.count} 人</strong></div>`).join('')}</div>`, button('查看客户', 'data-route="customers"'))}
  </div>
  <div class="two-column dashboard-detail-grid">
    ${card('项目业绩', table(['项目', '成交数', '成交金额', '退费金额', '净成交金额', '操作'], data.projectPerformance.map(row => [row.project, `${row.count} 单`, money(row.amount), money(row.refund), money(row.net), { html: button('查看明细', `data-modal="projectDetail" data-modal-id="${attr(row.project)}"`) }])), button('导出项目业绩', 'data-export="performance"'))}
    ${card('销售业绩', table(['销售', '成交数', '成交金额', '目标完成率'], data.dashboard.salesPerformance.map(row => [row.owner, `${row.count} 单`, money(row.amount), `${Math.min(100, Math.round(row.amount / 30000 * 100))}%`])))}
  </div>
  ${card('今日待办', `<div class="todo-list todo-list-horizontal"><button data-route="chat"><span>未回复会话</span><strong>3</strong></button><button data-route="followups"><span>今日应回访</span><strong>2</strong></button><button data-route="transactions"><span>待补合同</span><strong>${data.orders.filter(row => row.contractStatus === '待补录').length}</strong></button><button data-route="transactions"><span>退费审批中</span><strong>${data.refunds.filter(row => row.status === '审批中').length}</strong></button></div>`)}`;
};

const chatMessages = conversation => conversation.type === 'group' ? [
  ['incoming', '周念', '想了解一下联报课程，数学和英语可以一起报吗？', '10:08'],
  ['outgoing', '刘芸 · 企微 02号', '可以的，我把联报方案和时间表发到群里，大家都可以参考。', '10:10'],
  ['incoming', '陈一诺家长', '管理员能再说明一下优惠截止时间吗？', '10:16']
] : [
  ['incoming', conversation.name, '刘老师，我想了解一下课程安排，现在报名还来得及吗？', '10:08'],
  ['outgoing', '刘芸 · 企微 02号', '来得及的。我先把之前的咨询记录同步过来，避免您重复说明。', '10:10'],
  ['incoming', conversation.name, '好的，孩子现在数学大概110分，主要想冲刺压轴题。', '10:18'],
  ['outgoing', '刘芸 · 企微 02号', '明白，我给您推荐「高三数学冲刺 + 联报」方案，合同和课程安排稍后发您。', '10:20']
];
const chatConversationList = data => {
  const pins = data.ui?.pinnedConversationIds ?? new Set();
  return [...data.conversations].sort((a, b) => Number(pins.has(b.id)) - Number(pins.has(a.id))).map(row => `<button class="conversation-item ${row.id === conversationById(data)?.id ? 'active' : ''}" data-conversation="${e(row.id)}"><span class="avatar" style="background:${e(row.color)}">${e(row.short)}</span><span class="conversation-copy"><strong>${e(row.name)} ${pins.has(row.id) ? '<span class="pin-badge">置顶</span>' : ''}</strong><small>${e(row.preview)}</small></span><span class="conversation-meta"><time>${e(row.time)}</time>${row.unread ? `<b>${row.unread}</b>` : ''}</span></button>`).join('');
};
export const chatView = data => {
  const conversation = conversationById(data);
  const customer = customerById(data, conversation?.customerId);
  if (!conversation || !customer) return pending('暂无可展示会话。');
  const pinned = data.ui?.pinnedConversationIds?.has(conversation.id);
  const selectedAccount = data.ui?.activeAccountId || conversation.accountId;
  const messages = chatMessages(conversation).map(([side, who, content, time]) => `<div class="message-row ${side}"><span class="message-avatar">${e(who.slice(0, 1))}</span><div><small>${e(who)} · ${e(time)}</small><div class="message-bubble">${e(content)}</div></div></div>`).join('');
  return `<div class="chat-workspace"><aside class="conversation-panel"><div class="conversation-tools"><input aria-label="搜索会话" placeholder="搜索昵称、备注名或消息"><select aria-label="会话账号">${options(accountOptions(data), '')}</select></div><button class="capacity-card" data-modal="sessionCapacity"><span><strong>会话接入容量</strong><small>当前 286 / 建议上限 2,000</small></span><span>查看规则 ›</span><i><b style="width:14.3%"></b></i></button><div class="chat-tabs"><button class="active">全部</button><button>未回复 3</button><button>群聊</button></div><div class="conversation-list">${chatConversationList(data)}</div></aside>
    <section class="chat-main"><header class="chat-header"><div><strong>${e(conversation.name)}</strong><small>${conversation.type === 'group' ? `${conversation.members} 位成员 · 客户群` : `${e(customer.account)} · 归属 ${e(customer.ownerName)}`}</small></div><div class="chat-header-actions">${button(pinned ? '取消置顶' : '置顶会话', `data-toggle-pin="${e(conversation.id)}"`)}${button('录入成交', `data-modal="order" data-modal-id="${e(customer.id)}"`, true)}</div></header>${conversation.type === 'group' ? `<div class="group-reply-bar"><span>本次回复身份</span><select id="reply-account">${data.accounts.map(row => opt(row.id, row.label, selectedAccount)).join('')}</select>${selectedAccount === 'acc-admin' ? button('@所有人', 'data-modal="mentionAll"', true) : button('切换管理员后可 @所有人', 'data-modal="groupAccount"')}</div>` : ''}<div class="message-stream">${messages}</div><div class="composer"><div class="composer-tools">${button('⚡ 快捷回复', 'data-modal="quickReply"')}${button('发送图片', 'data-prototype-action="已选择图片（原型演示）"')}${button('发送文件', 'data-prototype-action="已选择文件（原型演示）"')}</div><textarea id="chat-input" placeholder="输入消息，Enter 发送">${e(data.ui?.composerText ?? '')}</textarea><div class="composer-foot"><span>Enter 发送 · Shift + Enter 换行</span>${button('发送', 'data-send-message', true)}</div></div></section>
    <aside class="customer-profile"><div class="profile-head"><span class="avatar large" style="background:${e(conversation.color)}">${e(customer.name.slice(0, 1))}</span><strong>${e(customer.name)}</strong><small>${e(customer.wechat)} · ${e(customer.account)}</small></div><section class="profile-section"><div class="section-row"><strong>客户信息</strong>${button('查看详情', `data-customer="${e(customer.id)}"`)}</div><dl><dt>手机号</dt><dd>${e(customer.phone)}</dd><dt>年级 / 院校</dt><dd>${e(customer.grade)} · ${e(customer.school)}</dd><dt>归属销售</dt><dd>${e(customer.ownerName)}</dd></dl></section><section class="profile-section"><div class="section-row"><strong>所在群聊</strong><span>${customer.groups.length} 个</span></div><div class="group-chips">${customer.groups.length ? customer.groups.map(group => `<button data-modal="groupAccount" data-modal-id="${attr(group)}">${e(group)} ›</button>`).join('') : '<small>暂未加入客户群</small>'}</div></section><section class="profile-section"><div class="section-row"><strong>标签</strong>${button('+ 添加', `data-modal="tagManage" data-modal-id="${e(customer.id)}"`)}</div><div class="tags">${customer.tags.map(tag => `<span class="tag">${e(tag)}</span>`).join('')}</div></section><section class="profile-section visit-card"><div class="section-row"><strong>回访设置</strong>${button('设置', `data-modal="followup" data-modal-id="${e(customer.id)}"`)}</div><p>下次回访：<b>${e(customer.nextVisit || '未设置')}</b></p><p>到期前 30 分钟提醒</p></section><section class="profile-section"><strong>业务快捷入口</strong><div class="profile-actions">${button('咨询记录', `data-modal="record" data-modal-id="${e(customer.id)}"`)}${button('录入成交', `data-modal="order" data-modal-id="${e(customer.id)}"`)}${button('交接流程', `data-modal="handover" data-modal-id="${e(customer.id)}"`)}</div></section></aside></div>`;
};

const tagStats = data => [...Map.groupBy(data.allCustomers.flatMap(customer => customer.tags.map(tag => ({ tag, customer }))), row => row.tag)].map(([tag, rows]) => ({ tag, count: rows.length }));
export const customersView = data => `${filterBar(data)}<div class="sync-banner"><span>✓</span><div><strong>企微原标签会保留</strong><p>首次全量同步会读取现有标签，同名标签不重复；上线工作台后仍可继续使用。</p></div>${button('查看同步规则', 'data-modal="tagSync"')}</div><div class="overview-grid customer-kpis">${card('授权账号联系人', `<strong class="metric-value">${data.allCustomers.length}</strong><p>${data.accounts.length} 个企微账号</p>`)}${card('当前筛选人数', `<strong class="metric-value">${data.customers.length}</strong><p>按添加时间、账号和标签去重</p>`)}${card('标签总数', `<strong class="metric-value">${data.tagOptions.length}</strong><p>点击下方标签查看明细</p>`)}${card('今日新增', '<strong class="metric-value">1</strong><p>2026-11-10</p>')}</div>${card('标签人数及明细', `<div class="tag-stat-grid">${tagStats(data).map(row => `<button class="tag-stat-card" data-modal="tagDetail" data-modal-id="${attr(row.tag)}"><span>${e(row.tag)}</span><strong>${row.count} 人</strong><small>查看明细 ›</small></button>`).join('')}</div>`, button('标签管理', 'data-modal="tagManage"'))}${card('全部账号联系人', table(['客户', '企微账号', '归属销售', '添加时间', '标签', '操作'], data.customers.map(row => [{ html: `<button class="link-btn" data-customer="${e(row.id)}">${e(row.name)}</button><small class="cell-sub">${e(row.wechat)}</small>` }, row.account, row.ownerName, row.addedAt.slice(0, 10), row.tags.join('、'), { html: `<div class="action-row">${button('会话', `data-open-chat="${e(row.id)}"`)}${button('详情', `data-customer="${e(row.id)}"`)}</div>` }]), '没有匹配联系人'))}`;
export const customerDetail = (data, id) => { const customer = customerById(data, id); if (!customer) return pending(TEXT.denied); const records = data.records.filter(row => row.customerId === customer.id); const orders = data.orders.filter(row => row.customerId === customer.id); return `<div class="detail-grid"><div>${card(customer.name, `<dl class="detail-list"><dt>微信号</dt><dd>${e(customer.wechat)}</dd><dt>手机号</dt><dd>${e(customer.phone)}</dd><dt>企微账号</dt><dd>${e(customer.account)}</dd><dt>归属销售</dt><dd>${e(customer.ownerName)}</dd><dt>添加时间</dt><dd>${e(customer.addedAt.slice(0, 10))}</dd></dl>`)}${card('所在群聊', customer.groups.map(group => `<span class="tag">${e(group)}</span>`).join('') || note('暂未加入群聊'))}</div><div>${card('标签', `<div class="tags">${customer.tags.map(tag => `<span class="tag">${e(tag)}</span>`).join('')}</div>`, button('管理标签', `data-modal="tagManage" data-modal-id="${e(customer.id)}"`))}${card('咨询与回访', table(['项目', '内容', '下次回访'], records.map(row => [row.project, row.content, row.nextVisit || '—'])))}${card('成交记录', table(['项目', '金额', '合同'], orders.map(row => [row.project, money(row.amount), row.contractStatus])))}</div></div>`; };

export const followupsView = data => { const tasks = data.allCustomers.filter(row => row.nextVisit); const groups = { today: tasks.filter(row => row.nextVisit === '2026-11-10'), overdue: tasks.filter(row => row.nextVisit < '2026-11-10'), future: tasks.filter(row => row.nextVisit > '2026-11-10') }; return `<div class="overview-grid followup-kpis">${card('今日应回访', `<strong class="metric-value">${groups.today.length}</strong><p>当天计划</p>`)}${card('未来 7 天', `<strong class="metric-value">${groups.future.length}</strong><p>即将到期</p>`)}${card('逾期未回访', `<strong class="metric-value warning">${groups.overdue.length}</strong><p>需要优先处理</p>`)}</div>${card('回访任务', table(['客户', '账号', '回访时间', '标签', '状态', '操作'], tasks.map(row => [row.name, row.account, row.nextVisit, row.tags.join('、'), row.nextVisit < '2026-11-10' ? '已逾期' : row.nextVisit === '2026-11-10' ? '今日' : '待回访', { html: `<div class="action-row">${button('进入会话', `data-open-chat="${e(row.id)}"`)}${button('修改计划', `data-modal="followup" data-modal-id="${e(row.id)}"`)}</div>` }])), button('新建回访', `data-modal="followup" data-modal-id="${e(data.allCustomers[0]?.id)}"`, true))}`; };
const recordRows = data => data.records.map(row => [row.customer, row.project, RECORD_KINDS[row.kind], row.content, row.recordedByName, row.createdDate, row.nextVisit || '—']);
export const recordsView = data => `${filterBar(data)}${card('咨询记录', table(['客户', '咨询项目', '类型', '咨询内容', '登记人', '登记日期', '下次回访'], recordRows(data)), button('新增咨询记录', 'data-modal="record"', true))}`;
const recordForm = (data, id = '') => form('saveRecord', `${customerSelect(data, id)}${input('project', '咨询项目', '', 'text', 'required', '例如：高三数学冲刺')}${select('kind', '记录类型', RECORD_KINDS, 'consultation')}${input('nextVisit', '下次回访', '', 'date')}${textarea('content', '咨询内容', '', 'required', '填写客户诉求、问题与建议方案')}`, data.actions.saveRecord.enabled, '保存记录');
export const dealFormView = (data, id = '') => `${note('成交后可继续补录合同；成交截图用于审批和财务核对。')}${form('saveOrder', `${customerSelect(data, id)}${input('project', '成交项目', '', 'text', 'required', '例如：2027届高考项目')}${input('product', '成交产品', '', 'text', 'required', '例如：高三数学冲刺班')}${input('amount', '成交金额', '', 'number', 'required min="0.01" step="0.01"', '例如：16800')}${input('dealDate', '成交日期', '2026-11-10', 'date')}${select('channel', '成交渠道', { wecom: '企业微信', bank: '银行转账', other: '其他' }, 'wecom')}${field('成交记录截图', '<div class="form-upload"><input name="attachment" type="file" accept="image/*"><span>上传收款、聊天或成交确认截图</span></div>', true)}`, data.actions.saveOrder.enabled, '确认录入')}`;
const refundForm = (data, id = '') => form('saveRefund', `${select('orderId', '关联成交单', Object.fromEntries(data.orders.map(row => [row.id, `${row.customer} · ${row.project} · ${money(row.amount)}`])), id || data.orders[0]?.id, 'required')}${input('amount', '申请退费金额', '', 'number', 'required min="0.01" step="0.01"', '不能超过原成交金额')}${textarea('reason', '退费原因', '', 'required', '填写退费原因和沟通结果')}${field('退费凭证', '<div class="form-upload"><input name="attachment" type="file" accept="image/*,.pdf"><span>上传聊天记录或退费材料</span></div>', true)}`, data.actions.saveRefund.enabled, '提交退费申请');
export const transactionsView = data => `${card('成交记录', table(['成交编号', '客户', '项目 / 产品', '金额', '成交截图', '合同', '操作'], data.orders.map(row => [row.id, row.customer, `${row.project} / ${row.product}`, money(row.amount), { html: `<button class="link-btn" data-modal="proof" data-modal-id="${e(row.id)}">${e(row.proofName)}</button>` }, row.contractStatus, { html: `<div class="action-row">${button('后补合同', `data-modal="contract" data-modal-id="${e(row.id)}"`)}${button('申请退费', `data-modal="refund" data-modal-id="${e(row.id)}"`)}</div>` }])), button('录入成交', 'data-modal="order"', true))}${card('退费申请', table(['申请编号', '客户', '关联成交', '金额', '原因', '状态', '申请时间'], data.refunds.map(row => [row.id, row.customer, row.orderId, money(row.amount), row.reason, row.status, row.createdDate])))}`;

export const renderTargetOptions = data => `<div class="target-options">${data.targets.map(row => `<label><input type="checkbox" name="targetIds" value="${e(row.id)}" ${data.targetIds.has(row.id) ? 'checked' : ''}>${e(row.name)}<span>${e((row.tags ?? []).join(' · '))}</span></label>`).join('')}</div>`;
const CONTENT_CONTROLS = { text: draft => textarea('content', '群发内容', draft.content, 'required', '输入群发内容'), link: draft => input('content', '公众号链接', draft.content, 'url', 'required', '粘贴链接'), attachment: draft => `${field('选择文件', `<input type="file" name="attachment" ${draft.attachment ? '' : 'required'}>`)}${note(draft.attachment?.name ?? '')}${textarea('content', '补充说明', draft.content)}` };
export const renderContentInput = (kind, draft = { content: '', attachment: null }) => CONTENT_CONTROLS[CONTENT_INPUTS[kind]](draft);
export const messagesView = data => `<div class="overview-grid">${card('今日任务', '<strong class="metric-value">2</strong><p>1 个待员工确认</p>')}${card('预计触达', '<strong class="metric-value">146</strong><p>客户与群成员</p>')}${card('已完成', '<strong class="metric-value">126</strong><p>成功送达</p>')}${card('失败 / 跳过', '<strong class="metric-value">2</strong><p>查看失败原因</p>')}</div>${card('群发任务', table(['任务', '发送对象', '内容类型', '内容', '状态', '操作'], data.tasks.map(row => [row.id, row.targets, CONTENT_KINDS[row.contentKind], row.attachment?.name ?? row.content, row.status, { html: button('查看结果', `data-prototype-action="已打开任务 ${e(row.id)} 的发送结果"`) }])), button('新建群发任务', 'data-modal="broadcast"', true))}`;
export const groupsView = data => `${card('客户群', table(['群名称', '人数', '所属账号', '归属销售', '分类', '操作'], data.groups.map(row => { const account = data.accounts.find(item => item.id === row.accountId); return [row.name, `${row.members} 人`, account?.label ?? row.accountId, row.ownerName, row.groupClass, { html: `<div class="action-row">${button('切换回复账号', `data-modal="groupAccount" data-modal-id="${e(row.id)}"`)}${button('管理员通知', `data-modal="mentionAll" data-modal-id="${e(row.id)}"`)}</div>` }]; })), button('群发通知', 'data-modal="broadcast"', true))}${card('接入说明', '<ul class="feature-list"><li>销售可切换自己已授权的工作账号回复。</li><li>切换管理员账号后可使用 @所有人，提交前二次确认。</li><li>群聊和成员由企业微信已授权账号同步。</li></ul>')}`;
export const statisticsView = data => `${card('项目成交总数和金额', table(['项目', '成交总数', '成交金额', '金额占比'], data.projectPerformance.map(row => [row.project, `${row.count} 单`, money(row.amount), `${Math.round(row.amount / Math.max(data.performance.total, 1) * 100)}%`]), '暂无成交数据'), button('导出项目业绩', 'data-export="performance"', true))}<div class="two-column">${card('销售排名', table(['排名', '销售', '成交单数', '成交金额'], [['1', '刘芸', data.orders.length, money(data.performance.total)]]))}${card('客户分布', data.dimensions.slice(0, 2).map(dimension => `<div class="distribution-row"><strong>${e(dimension.label)}</strong>${dimension.entries.map(row => `<span>${e(row.value)} ${row.count}</span>`).join('')}</div>`).join(''))}</div>`;
export const materialsView = () => `${card('共享素材', `${field('上传素材', '<input id="material-file" type="file" accept="image/*,.pdf,.doc,.docx">')}<div id="material-preview" class="material-preview"></div>${note(PENDING.materials)}${actionButton('保存素材', '素材已保存到本地演示列表', true)}`)}`;
export const phrasesView = data => `${card('个人快捷回复', table(['名称', '内容', '操作'], data.phrases.map(row => [row.title, row.content, { html: `<div class="action-row">${button('编辑', `data-edit-phrase="${e(row.id)}"`)}${button('删除', `data-delete-phrase="${e(row.id)}"`)}</div>` }])), button('新增话术', 'data-modal="phrase"', true))}`;
const phraseForm = (data, id = '') => { const phrase = data.phrases.find(row => row.id === id) ?? {}; return form('savePhrase', `<input name="id" type="hidden" value="${e(phrase.id)}">${input('title', '话术名称', phrase.title, 'text', 'required')}${textarea('content', '回复内容', phrase.content, 'required')}`, data.actions.savePhrase.enabled); };
export const exportView = data => {
  const projectItems = Object.fromEntries([['', '全部项目'], ...data.projectOptions.map(project => [project, project])]);
  const ownerItems = Object.fromEntries([['', '全部销售'], ...data.ownerOptions.map(owner => [owner, owner])]);
  const sourceItems = Object.fromEntries([['', '全部来源'], ...data.sourceOptions.map(source => [source, source])]);
  const counts = { customers: data.customers.length, consultation: data.recordQueries.consultation.length, followups: data.recordQueries.revisit.length, orders: data.orders.length, refunds: data.refunds.length, tagsGroups: data.customers.length, performance: data.projectPerformance.length };
  const descriptions = {
    customers: '客户ID、姓名、微信号、手机、来源、阶段、企微号、归属、标签与群聊',
    consultation: '咨询项目、咨询内容、登记人、登记时间及下次回访',
    followups: '回访项目、回访内容、回访人、回访时间及下次回访',
    orders: '成交项目、产品、金额、渠道、截图、合同状态及客户归属',
    refunds: '原成交单、退费金额、原因、审批状态和申请时间',
    tagsGroups: '客户标签、所在群聊、所属企微号及归属销售',
    performance: '项目成交数、成交金额、退费金额及净成交金额'
  };
  return `<form class="toolbar export-filter" data-filter><div class="filters">${input('start', '数据开始日期', data.filters.start, 'date')}${input('end', '数据结束日期', data.filters.end, 'date')}${select('project', '项目', projectItems, data.filters.project)}${select('account', '企微账号', accountOptions(data), data.filters.account)}${select('owner', '归属销售', ownerItems, data.filters.owner)}${select('source', '客户来源', sourceItems, data.filters.source)}</div><div class="filter-actions">${button('重置', 'type="button" data-reset-filter')}${button('应用筛选', 'type="submit"', true)}</div></form>
  <div class="migration-note"><span>数据库迁移字段</span><div><strong>保留常用基础字段，可直接对应旧系统数据</strong><p>导出字段采用稳定中文表头；客户ID、归属、时间、项目、标签等关键字段默认选中，也可按业务需要自定义。</p></div>${button('查看全部字段', 'data-modal="exportFields" data-modal-id="customers"')}</div>
  <div class="export-card-grid">${data.exports.map(item => `<section class="export-data-card"><div class="export-data-head"><span>${e(item.title.slice(0, 1))}</span><div><strong>${e(item.title)}</strong><small>${counts[item.id] ?? 0} 条可导出</small></div></div><p>${e(descriptions[item.id])}</p><div class="export-data-actions">${button('选择字段', `data-modal="exportFields" data-modal-id="${e(item.id)}"`)}${button('立即导出', `data-export="${e(item.id)}"`, true)}</div></section>`).join('')}</div>
  ${card('数据预览', table(['客户', '来源 / 阶段', '企微账号', '归属销售', '添加时间', '标签'], data.customers.slice(0, 5).map(row => [row.name, `${row.source} / ${row.stage}`, row.account, row.ownerName, row.addedAt.slice(0, 10), row.tags.join('、')])), button('配置导出字段', 'data-modal="exportFields" data-modal-id="customers"'))}
  ${card('最近导出记录', table(['文件名称', '导出类型', '数据范围', '记录数', '操作人', '生成时间', '操作'], [
    ['客户基础资料_20261109.csv', '客户基础资料', '企微 02号', '126', '刘芸', '2026-11-09 17:26', { html: button('重新下载', 'data-prototype-action="已重新生成客户基础资料文件（原型演示）"') }],
    ['销售业绩报表_20261108.csv', '销售业绩报表', '全部授权账号', '8', '管理员', '2026-11-08 18:10', { html: button('重新下载', 'data-prototype-action="已重新生成销售业绩报表（原型演示）"') }]
  ]), button('清理记录', 'data-prototype-action="历史导出记录已清理（原型演示）"'))}`;
};
export const settingsView = data => `${card('企微账号', table(['账号', '角色', '同步状态', '操作'], data.accounts.map(row => [row.label, row.role, '同步正常', { html: button('查看', 'data-prototype-action="已打开账号同步详情"') }]))) }${card('标签同步与保留', `<div class="sync-setting"><span class="sync-icon">✓</span><div><strong>保留企业微信原有标签</strong><p>上线首次全量同步读取已有标签；同名标签合并，不会删除企微侧标签。后续每日增量同步。</p></div>${button('查看同步规则', 'data-modal="tagSync"')}</div>`)}${card('角色与数据范围', table(['角色', '范围', '能力'], [[ROLES.admin.label, '全部企微账号', '配置、查看和导出'], [ROLES.supervisor.label, '授权团队', '团队业务管理'], [ROLES.sales.label, '本人授权账号', '本人客户与会话']]))}`;

const views = { dashboard: dashboardView, chat: chatView, customers: customersView, followups: followupsView, records: recordsView, transactions: transactionsView, messages: messagesView, groups: groupsView, statistics: statisticsView, materials: materialsView, phrases: phrasesView, export: exportView, settings: settingsView };
export const renderRoute = (route, data) => views[route]?.(data) ?? pending('页面暂不可用');
export const renderShell = (route, data) => { const definition = data.routes.find(item => item.id === route) ?? data.routes[0]; return `<div class="app-shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">警</div><div class="brand-text"><strong>警然 SCRM</strong><span>WEWORK CRM</span></div></div><nav class="nav-group"><div class="nav-label">业务中心</div>${data.routes.map(item => `<button class="nav-item ${item.sub ? 'sub' : ''} ${item.id === route ? 'active' : ''}" data-route="${item.id}">${icon(item.icon)}<span class="nav-name">${e(item.title)}</span></button>`).join('')}</nav><div class="sidebar-foot"><div class="scope-card"><small>当前数据范围</small>${e(ROLES[data.role].scopeLabel)}</div></div></aside><main class="main-wrap"><header class="topbar"><div class="crumb"><span>警然教育</span><span>/</span><strong>${e(definition.title)}</strong></div><div class="top-actions"><span class="preview-label">高保真交互原型</span><div class="role-switch">${Object.entries(ROLES).map(([id, role]) => `<button class="role-button ${id === data.role ? 'active' : ''}" data-role="${id}">${e(role.label)}</button>`).join('')}</div></div></header><section class="content ${route === 'chat' ? 'chat-page' : ''}"><div class="preview-note">演示数据 · 未连接真实企微 · 所有操作仅用于原型体验</div>${route === 'chat' ? '' : `<div class="page-head"><div><h1 class="page-title">${e(definition.title)}</h1><p class="page-subtitle">${e(definition.description)}</p></div></div>`}<div role="status" class="result-banner ${e(data.result.status)}" ${data.result.message ? '' : 'hidden'}>${e(data.result.message)}</div>${renderRoute(route, data)}</section></main></div>`; };

const followupForm = (data, id = '') => { const customer = customerById(data, id); return form('saveNextVisit', `<input type="hidden" name="customerId" value="${e(customer?.id)}">${field('客户', `<div class="readonly-field">${e(customer?.name ?? '')}</div>`)}${input('nextVisit', '下次回访日期', customer?.nextVisit ?? '', 'date', 'required')}${select('reminder', '提醒时间', { '30': '提前 30 分钟', '60': '提前 1 小时', '1440': '提前 1 天' }, '30')}${textarea('note', '回访备注', '', '', '例如：确认合同和上课安排')}`, data.actions.saveNextVisit.enabled, '保存回访计划'); };
const tagManage = (data, id = '') => { const customer = customerById(data, id); return `<form data-form="saveTags"><input type="hidden" name="customerId" value="${e(customer?.id)}"><p class="modal-lead">${e(customer?.name)} · 勾选后保存，原企微标签不会被删除。</p><div class="checkbox-grid">${data.tagOptions.map(tag => `<label><input type="checkbox" name="tags" value="${e(tag)}" ${customer?.tags.includes(tag) ? 'checked' : ''}>${e(tag)}</label>`).join('')}</div><div class="form-actions"><span>首次同步保留企微原标签</span>${button('保存标签', 'type="submit"', true)}</div></form>`; };
const quickReply = data => `<div class="quick-reply-list">${data.phrases.map(row => `<button data-use-phrase="${attr(row.content)}"><strong>${e(row.title)}</strong><span>${e(row.content)}</span><small>使用此回复 ›</small></button>`).join('')}</div>`;
const sessionCapacity = () => `<div class="capacity-detail"><div class="capacity-number"><strong>286</strong><span>/ 2,000 个活跃会话</span></div><div class="capacity-meter"><i style="width:14.3%"></i></div><ul class="feature-list"><li>本原型按每个工作台建议展示最多 2,000 个活跃会话设计。</li><li>超过展示容量的历史会话仍可通过客户姓名、手机号或微信号搜索。</li><li>真实上限取决于企业微信接口、授权账号数量和正式部署配置，需在实施阶段确认。</li></ul></div>`;
const handoverView = (data, id = '') => { const customer = customerById(data, id); return `<div class="handover-summary"><strong>${e(customer?.name)}</strong><span>当前归属：${e(customer?.ownerName)} · ${e(customer?.account)}</span></div><div class="flow-steps"><div class="flow-step done"><b>1</b><div><strong>发起交接</strong><p>选择接收销售和交接原因。</p></div></div><div class="flow-step active"><b>2</b><div><strong>原销售收到通知</strong><p>原销售可查看客户、咨询、回访和成交记录，并确认交出。</p></div></div><div class="flow-step"><b>3</b><div><strong>新销售接受</strong><p>接受后客户进入新销售工作台，原销售保留只读交接记录。</p></div></div><div class="flow-step"><b>4</b><div><strong>全程留痕</strong><p>系统记录双方、时间和数据范围，管理员可追溯。</p></div></div></div>${field('接收销售', '<select><option>莎莎 · 企微 03号</option><option>刘芸 · 企微 02号</option></select>')}${actionButton('发起交接', '交接申请已发送给原销售和接收销售（原型演示）', true)}`; };
const contractView = (data, id = '') => { const order = data.orders.find(row => row.id === id) ?? data.orders[0]; return `<div class="contract-order"><strong>${e(order?.id)}</strong><span>${e(order?.customer)} · ${e(order?.project)} · ${money(order?.amount)}</span></div><div class="form-grid">${input('contractNo', '合同编号', '', 'text', '', '例如：HT20261110001')}${input('signedDate', '签署日期', '2026-11-10', 'date')}${field('合同文件', '<div class="form-upload"><input type="file" accept=".pdf,image/*"><span>支持后置上传 PDF 或图片</span></div>', true)}</div>${actionButton('保存合同', '合同已补录并关联成交记录（原型演示）', true)}`; };
const proofView = (data, id = '') => { const order = data.orders.find(row => row.id === id) ?? data.orders[0]; return `<div class="proof-preview"><div class="proof-placeholder"><span>成交记录截图</span><strong>${e(order?.proofName)}</strong><small>静态原型不展示真实客户凭证</small></div><dl><dt>成交客户</dt><dd>${e(order?.customer)}</dd><dt>项目</dt><dd>${e(order?.project)}</dd><dt>金额</dt><dd>${money(order?.amount)}</dd></dl></div>`; };
const broadcastView = data => `<div class="form-grid">${select('targetType', '发送对象', TARGET_KINDS, 'customers')}${select('account', '发送账号', accountOptions(data), '')}${select('tag', '客户标签', { '': '全部标签', ...Object.fromEntries(data.tagOptions.map(tag => [tag, tag])) }, '')}${select('schedule', '发送时间', { now: '保存后员工确认', later: '预约发送' }, 'now')}${textarea('broadcastContent', '群发内容', '', 'required', '输入文本、课程通知或活动提醒')}</div><div class="confirm-box">预计触达 18 人 · 正式发送前需员工在企业微信确认</div>${actionButton('创建群发任务', '群发任务已创建，等待员工确认（原型演示）', true)}`;
const groupAccountView = (data, id = '') => `<p class="modal-lead">${e(id && !id.startsWith('group-') ? id : '选择用于回复群聊的工作账号')}</p><div class="account-list">${data.accounts.map(row => `<button data-set-reply-account="${e(row.id)}"><span><strong>${e(row.label)}</strong><small>${e(row.role)}</small></span><b>${row.id === 'acc-admin' ? '可 @所有人' : '切换'}</b></button>`).join('')}</div>`;
const mentionAllView = () => `<div class="warning-panel"><strong>确认使用管理员账号 @所有人？</strong><p>该通知会提醒群内全部成员。正式发送前需要管理员再次确认，并保留操作记录。</p></div>${textarea('notice', '通知内容', '请大家关注最新课程安排，有问题可在群内咨询。')}${actionButton('确认 @所有人', '管理员通知已提交（原型演示）', true)}`;
const tagDetailView = (data, tag = '') => { const rows = data.allCustomers.filter(row => row.tags.includes(tag)); return `${note(`标签「${tag}」共 ${rows.length} 人`)}${table(['客户', '企微账号', '归属销售', '添加时间'], rows.map(row => [row.name, row.account, row.ownerName, row.addedAt.slice(0, 10)]))}`; };
const tagSyncView = () => `<div class="flow-steps"><div class="flow-step done"><b>1</b><div><strong>首次全量读取</strong><p>读取已授权企微账号内客户与已有标签。</p></div></div><div class="flow-step active"><b>2</b><div><strong>保留并去重</strong><p>同名标签合并，不删除企业微信侧原标签。</p></div></div><div class="flow-step"><b>3</b><div><strong>每日增量同步</strong><p>新增、修改标签继续同步，异常可重新补查。</p></div></div></div>${actionButton('模拟立即同步', '标签同步完成：已有标签均已保留（原型演示）', true)}`;
const projectDetailView = (data, project = '') => { const rows = project ? data.orders.filter(row => row.project === project) : data.orders; return `${note(project ? `项目：${project}` : '全部成交项目')}${table(['客户', '项目', '产品', '金额', '归属销售'], rows.map(row => [row.customer, row.project, row.product, money(row.amount), row.customerOwner]))}`; };
const exportFieldsView = (data, id = 'customers') => {
  const definition = data.exports.find(row => row.id === id) ?? data.exports[0];
  return `<div class="export-fields-head"><div><strong>${e(definition?.title)}</strong><p>常用基础字段默认勾选，方便与旧数据库建立稳定映射。</p></div><span>${definition?.headers.length ?? 0} 个字段</span></div><div class="export-field-toolbar"><label><input type="checkbox" checked> 全选当前分组</label>${button('恢复默认', 'data-prototype-action="已恢复默认导出字段（原型演示）"')}</div><div class="checkbox-grid export-field-grid">${(definition?.headers ?? []).map((header, index) => `<label><input type="checkbox" checked ${index < 3 ? 'disabled' : ''}><span>${e(header)}</span>${index < 3 ? '<small>迁移必选</small>' : ''}</label>`).join('')}</div><div class="export-format-options"><strong>文件格式</strong><label><input type="radio" name="format" checked> CSV（兼容 Excel）</label><label><input type="radio" name="format"> XLSX</label></div><div class="form-actions"><span>敏感字段按当前角色权限脱敏</span><div>${button('保存为常用模板', 'data-prototype-action="已保存为常用导出模板（原型演示）"')}${button('按所选字段导出', `data-export="${e(definition?.id)}"`, true)}</div></div>`;
};

const MODALS = { order: ['录入成交', dealFormView], refund: ['申请退费', refundForm], record: ['新增咨询记录', recordForm], phrase: ['快捷回复话术', phraseForm], customer: ['客户详情', customerDetail], sessionCapacity: ['会话接入容量说明', sessionCapacity], quickReply: ['选择快捷回复', quickReply], mentionAll: ['管理员群通知', mentionAllView], followup: ['设置回访', followupForm], handover: ['客户交接流程', handoverView], contract: ['后补合同', contractView], proof: ['成交截图', proofView], broadcast: ['新建群发任务', broadcastView], tagDetail: ['标签人数明细', tagDetailView], tagManage: ['标签管理', tagManage], projectDetail: ['项目成交明细', projectDetailView], groupAccount: ['切换群聊回复账号', groupAccountView], tagSync: ['企微标签同步规则', tagSyncView], exportFields: ['选择导出字段', exportFieldsView] };
export const renderModal = (type, data, id = '') => { const definition = MODALS[type]; if (!definition) return ''; const [title, view] = definition; return `<div class="modal-backdrop" data-modal-backdrop><section class="modal ${['customer', 'projectDetail'].includes(type) ? 'modal-wide' : ''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${e(title)}</h2>${button('关闭', 'data-close-modal')}</div><div class="modal-body">${view(data, id)}</div></section></div>`; };
